%root_path = fileparts(mfilename("fullpath"));
%root_path = pwd;

% retrieve selected cuts used for further fitting
[GP_FFCutsFits,CutFitFileGP] = recover_selected_cuts('GP_FFCutsFits','e:\SHARE\Fe\Data\analysis\07_fit_with_multicut_allJ\sel_cuts');

%%
fn = fieldnames(GP_FFCutsFits);
%nf = 11
%for nf = 2:numel(fn)
%selectCuts = fn{nf};
selectCuts = 'Ei200_off110GPminFF';
if ismember(selectCuts(1:3),{'msk','dat'})||...
        contains(selectCuts,'all_fit_par')
    %continue
    error('Can not fit field: %s',selectCuts);
end


fprintf('Processing cuts: %s \n', selectCuts); %[output:3783f932]
%selectCuts= 'Ei400_off200GPmaxFF';
cuts_list = GP_FFCutsFits.(selectCuts);
if ~iscell(cuts_list)
    cuts_list = {cuts_list};
end
if contains(selectCuts,'Ei200')
    min_Ei = 30;
    mi = maps_instrument(200,600,'S');
end
if contains(selectCuts,'Ei400')
    min_Ei = 40;
    mi = maps_instrument(401,600,'S');
end
if contains(selectCuts,'Ei800')
    min_Ei =70;
    mi = maps_instrument(786,600,'S');
end
sample=IX_sample(true,[1,0,0],[0,1,0],'cuboid',[0.04,0.03,0.02]);
for j=1:numel(cuts_list)
    cuts_list{j} = cuts_list{j}.set_instrument(mi);
    cuts_list{j} = cuts_list{j}.set_sample(sample);
    plot(cuts_list{j}); lz 0 1; keep_figure;
end
dir_name  = "GP";

dE_step = 2; %original energy transfer step data were binned to. No point in going finer
half_dE = 5; % half width of data binning

en_mm = cuts_list{1}.data.img_range(:,4);
en_mm(1) = max(min_Ei,en_mm(1));
%en_mm(1) = 100;
%en_mm(2) = 170;
cut_en = en_mm(1)+half_dE:2*half_dE:(en_mm(2)-half_dE);

cut_dimensions = 1;
GP_FFCutsFits.(selectCuts) = cuts_list;

GP_FFCutsFits = fit_multicutsFF_along_direction(... %[output:group:4fa25ffe] %[output:9afb5ddf] %[output:07770fb7] %[output:47656ab0] %[output:45602f36] %[output:8a6ee04b] %[output:9d1a56eb] %[output:624efa13] %[output:2f3431e5] %[output:5513adf3]
    GP_FFCutsFits,selectCuts,cut_dimensions,cut_en,dE_step,half_dE,false); %[output:group:4fa25ffe] %[output:9afb5ddf] %[output:07770fb7] %[output:47656ab0] %[output:45602f36] %[output:8a6ee04b] %[output:9d1a56eb] %[output:624efa13] %[output:2f3431e5] %[output:5513adf3]
cl = GP_FFCutsFits.(selectCuts);
GP_FFCutsFits.(selectCuts) = [cl{:}];

beep
beep
beep

all_fit_par = GP_FFCutsFits.([selectCuts,'_all_fit_par']);
bg_data = extract_bg_par(all_fit_par,[1,2]);
% original slope parameters
pd(bg_data(1));lx(all_fit_par(1).en,all_fit_par(end).en);keep_figure;
pd(bg_data(2));lx(all_fit_par(1).en,all_fit_par(end).en);keep_figure
%pd(bg_data(3));lx(fit_res.peak_fit_par(1).en,fit_res.peak_fit_par(end).en);keep_figure;
%pd(bg_data(4));lx(fit_res.peak_fit_par(1).en,fit_res.peak_fit_par(end).en);keep_figure
%%

doc = matlab.desktop.editor.getActive;
doc.save;
thisFile = 'e:\SHARE\Fe\Data\analysis\06_fit_with_AQ0\fit_cutFe_GP.mlx';
targ_file = fullfile(fileparts(thisFile),['fit_cutFe_GP_',selectCuts,'.pdf']);
export(thisFile,targ_file);
%close all;

fit_src_struc = GP_FFCutsFits;
save(CutFitFileGP,"fit_src_struc",'-v7.3')
%end

